import{_ as a,a0 as o,w as r,s as i,ao as l,I as p,x as n,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——在Ubuntu中添加用户 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Adding User Accounts In Ubuntu","title":"每日Ubuntu小技巧——在Ubuntu中添加用户","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Adding User Accounts In Ubuntu.md","filePath":"[post].md"}'),b={name:"201311/Daily Ubuntu Tips – Adding User Accounts In Ubuntu.md"};function d(g,t,U,m,w,T){const u=o("Link");return r(),i("div",null,[t[11]||(t[11]=l('<h1 id="每日ubuntu小技巧——在ubuntu中添加用户" tabindex="-1">每日Ubuntu小技巧——在Ubuntu中添加用户 <a class="header-anchor" href="#每日ubuntu小技巧——在ubuntu中添加用户" aria-label="Permalink to “每日Ubuntu小技巧——在Ubuntu中添加用户”">​</a></h1><p>Ubuntu是一个多用户操作系统。多用户操作系统意味着多个用户可以通过独立的、个人的HOME文件夹，文件和设置访问计算机。用户<strong>A</strong>可以登录并修改他/她自己的配置文件而不会影响用户<strong>B</strong>的配置文件。</p><p>因此，你可以为每一个可能使用你家里电脑的用户创建一个独立的账户，而不是仅仅为所有人创建一个共享的账户。本文将展示使用Ubuntu时如何实现这一点。</p><p>为了获得上面所说的那样的独立账户，首先点击长条菜单栏上的齿轮图标，然后点击系统设置。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable4.png" alt=""></p><p>当如图所示的窗口打开后，点击屏幕下方的“<strong>用户账户（User Accounts）</strong>”，如下图所示。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu.png" alt=""></p><p>要添加用户到你的Ubuntu需要管理员权限，请在添加账户前点击解锁（Unlock)。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu1.png" alt=""></p><p>然后，点击加号（ + ）按钮来创建用户账户。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu2.png" alt=""></p><p>创建用户时有两种基本的账户类型： <strong>标准用户</strong> 和 <strong>管理员</strong> 。管理员权限用户有权限删除用户，安装软件和驱动，修改日期和时间，或者进行一些可能使计算机不稳定的操作。</p><p>标准用户不能进行这些操作。他/她只能够修改自己的个人设置里面的东西。</p><p>输入用户全名时，系统将根据全名自动选择用户名。你可以保留自动生成的用户名，也可以根据需要修改用户名。完成后，点击<strong>创建（Create)</strong>来创建账户。</p><p>默认情况下，刚创建的账户是不可用的，除非给他设置或修改了密码。要想让账户可用，点击账户的不可用按钮，然后输入密码。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/useraccountsubuntu3.png" alt=""></p><p>如果你想要用户自动登录而不用输入密码，你可以在设置他/她登录密码的时候选择下拉选项中的自动登录。</p><h2 id="enjoy" tabindex="-1">Enjoy! <a class="header-anchor" href="#enjoy" aria-label="Permalink to “Enjoy!”">​</a></h2>',18)),p("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-user-accounts-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-user-accounts-ubuntu/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原创翻译，",-1)),e(u,{href:"http://linux.cn/"},{default:s(()=>[...t[3]||(t[3]=[n("Linux中国",-1)])]),_:1}),t[6]||(t[6]=n(" 荣誉推出",-1))]),p("p",null,[t[9]||(t[9]=n("译者：",-1)),e(u,{href:"https://github.com/scusjs"},{default:s(()=>[...t[7]||(t[7]=[n("SCUSJS",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),e(u,{href:"https://github.com/jasminepeng"},{default:s(()=>[...t[8]||(t[8]=[n("jasmiepeng",-1)])]),_:1})])])}const k=a(b,[["render",d]]);export{C as __pageData,k as default};
